4238	    function streamIntoElement(targetEl, text, options) {
4239	      var speed = (options && options.speed) || 22;
4240	      var onDone = (options && options.onDone) || function() {};
4241	      var index = 0;
4242	      targetEl.textContent = "";
4243	      var tick = function() {
4244	        index += Math.max(1, text[index] === " " ? 2 : 1);
4245	        targetEl.textContent = text.slice(0, index);
4246	        if (index < text.length) {
4247	          window.setTimeout(tick, speed);
4248	        } else {
4249	          onDone();
4250	        }
4251	      };
4252	      window.setTimeout(tick, 30);
4253	    }
